import { useEffect } from 'react'
import { useDispatch, useSelector } from 'react-redux'
import { apiSlice } from '~/api/api-slice'
import { useLogoutMutation, authApi } from '~/api/auth.api'
import { postLogoutBroadcast, subscribeLogoutBroadcast } from '~/modules/auth/lib/broadcast-auth'
import type { AuthState } from '~/modules/auth/models/auth.model'
import { loggedOut, sessionVerified } from '~/modules/auth/store/auth.slice'
import type { AppDispatch, RootState } from '~/modules/app/app.store'

export interface UseAuthReturn {
  status: AuthState['status']
  user: AuthState['user']
  isAuthenticated: boolean
  isUnknown: boolean
  isUnauthenticated: boolean
}

export const useAuth = (): UseAuthReturn => {
  const { status, user } = useSelector((state: RootState) => state.auth)
  return {
    status,
    user,
    isAuthenticated: status === 'authenticated',
    isUnknown: status === 'unknown',
    isUnauthenticated: status === 'unauthenticated',
  }
}

export interface UseSignOutReturn {
  signOut: () => Promise<void>
  isSigningOut: boolean
}

export const useSignOut = (): UseSignOutReturn => {
  const dispatch = useDispatch<AppDispatch>()
  const [logout, { isLoading }] = useLogoutMutation()

  const signOut = async (): Promise<void> => {
    try {
      await logout(undefined).unwrap()
    } finally {
      dispatch(loggedOut())
      dispatch(apiSlice.util.resetApiState())
      postLogoutBroadcast()
    }
  }

  return { signOut, isSigningOut: isLoading }
}

export const useAuthBootstrap = (): void => {
  const dispatch = useDispatch<AppDispatch>()

  useEffect(() => {
    let cancelled = false

    const bootstrap = async (): Promise<void> => {
      const xsrfPromise = dispatch(authApi.endpoints.xsrf.initiate(undefined))
      try {
        await xsrfPromise.unwrap()
      } catch {
      } finally {
        xsrfPromise.unsubscribe()
      }

      if (cancelled) return

      const mePromise = dispatch(authApi.endpoints.me.initiate(undefined))
      try {
        const me = await mePromise.unwrap()
        if (!cancelled) {
          dispatch(sessionVerified({ userId: me.userId, email: me.email }))
        }
      } catch {
        if (!cancelled) dispatch(loggedOut())
      } finally {
        mePromise.unsubscribe()
      }
    }

    void bootstrap()

    return () => {
      cancelled = true
    }
  }, [dispatch])
}

export const useAuthBroadcastListener = (): void => {
  const dispatch = useDispatch<AppDispatch>()
  useEffect(
    () =>
      subscribeLogoutBroadcast(() => {
        dispatch(loggedOut())
        dispatch(apiSlice.util.resetApiState())
      }),
    [dispatch],
  )
}

import { Eye, EyeOff } from 'lucide-react'

import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

export interface PasswordVisibilityToggleProps {
  isVisible: boolean
  onToggle: () => void
  className?: string
}

export const PasswordVisibilityToggle = ({
  isVisible,
  onToggle,
  className,
}: PasswordVisibilityToggleProps) => (
  <Button
    type="button"
    variant="ghost"
    size="icon"
    aria-label={isVisible ? 'Hide password' : 'Show password'}
    aria-pressed={isVisible}
    onClick={onToggle}
    className={cn('absolute top-1/2 right-1 -translate-y-1/2', className)}
  >
    {isVisible ? <EyeOff aria-hidden="true" /> : <Eye aria-hidden="true" />}
  </Button>
)
